export function validateCheckIn(body) {
  const errors = []

  if (!body.date || !DATE_REGEX.test(body.date)) {
    errors.push('date must be in YYYY-MM-DD format')
  } else {
    const parsed = new Date(body.date + 'T00:00:00Z')
    if (isNaN(parsed.getTime())) {
      errors.push('date is not a valid calendar date')
    }
  }

  const scoreFields = [
    ['physicalScore', 'Physical'],
    ['mentalScore', 'Mental'],
    ['emotionalScore', 'Emotional'],
    ['identityScore', 'Identity / Purpose'],
  ]

  for (const [field, label] of scoreFields) {
    const val = body[field]
    if (val === undefined || val === null) {
      errors.push(`${label} score is required`)
    } else if (!Number.isInteger(val) || val < 1 || val > 10) {
      errors.push(`${label} score must be an integer between 1 and 10`)
    }
  }

  return errors
}

export function sanitizeCheckIn(body) {
  return {
    date: body.date,
    physicalScore: body.physicalScore,
    physicalHelped: body.physicalHelped || '',
    physicalDrained: body.physicalDrained || '',
    mentalScore: body.mentalScore,
    mentalHelped: body.mentalHelped || '',
    mentalDrained: body.mentalDrained || '',
    emotionalScore: body.emotionalScore,
