async function request(url, options = {}) {
  const res = await fetch(url, {
    headers: { 'Content-Type': 'application/json' },
    ...options,
  })
  if (res.status === 204) return null
  if (res.headers.get('content-type')?.includes('text/csv')) {
    return res.blob()
  }
  const data = await res.json()
  if (!res.ok) throw new Error(data.error || 'Request failed')
  return data
}

export function getToday() {
  return request(`${BASE}/today`)
}

export function getCheckIns(from, to) {
  const params = new URLSearchParams()
  if (from) params.set('from', from)
  if (to) params.set('to', to)
  const qs = params.toString()
  return request(`${BASE}${qs ? `?${qs}` : ''}`)
}

export function getCheckIn(id) {
  return request(`${BASE}/${id}`)
}

export function createCheckIn(data) {
  return request(BASE, {
    method: 'POST',
    body: JSON.stringify(data),
  })
}

export function updateCheckIn(id, data) {
  return request(`${BASE}/${id}`, {
    method: 'PUT',
    body: JSON.stringify(data),
  })
}

export function deleteCheckIn(id) {
  return request(`${BASE}/${id}`, { method: 'DELETE' })
}

export function getTrends(period = '7d') {
  return request(`${BASE}/trends?period=${period}`)
}

export function exportCSV(from, to) {
  const params = new URLSearchParams()
  if (from) params.set('from', from)
  if (to) params.set('to', to)
  const qs = params.toString()
  window.location.href = `${BASE}/export${qs ? `?${qs}` : ''}`
}
"}

