import db from '../db.js'
import { validateCheckIn, sanitizeCheckIn } from '../validation.js'

const router = Router()

function todayDate() {
  return new Date().toISOString().split('T')[0]
}

// GET /api/checkins/today
router.get('/today', (req, res) => {
  const row = db.prepare('SELECT * FROM checkins WHERE date = ?').get(todayDate())
  if (!row) return res.status(404).json({ error: 'No check-in found for today' })
  res.json(row)
})

// GET /api/checkins/trends
router.get('/trends', (req, res) => {
  const validPeriods = { '7d': 7, '14d': 14, '30d': 30, '90d': 90 }
  const period = req.query.period || '7d'
  const days = validPeriods[period] || 7

  const to = todayDate()
  const fromDate = new Date()
  fromDate.setDate(fromDate.getDate() - days + 1)
  const from = fromDate.toISOString().split('T')[0]

  const rows = db.prepare(
    'SELECT * FROM checkins WHERE date >= ? AND date <= ? ORDER BY date ASC'
  ).all(from, to)

  if (rows.length === 0) {
    return res.json({
      period,
      from,
      to,
      totalEntries: 0,
      averages: { physical: 0, mental: 0, emotional: 0, identity: 0 },
      lowestMostOften: null,
      dailyScores: [],
    })
  }

  const sums = { physical: 0, mental: 0, emotional: 0, identity: 0 }
  const lowestCount = { physical: 0, mental: 0, emotional: 0, identity: 0 }

  const dailyScores = rows.map(row => {
    sums.physical += row.physicalScore
    sums.mental += row.mentalScore
    sums.emotional += row.emotionalScore
    sums.identity += row.identityScore

    const scores = {
      physical: row.physicalScore,
      mental: row.mentalScore,
      emotional: row.emotionalScore,
      identity: row.identityScore,
    }
    const min = Math.min(...Object.values(scores))
    for (const [key, val] of Object.entries(scores)) {
      if (val === min) lowestCount[key]++
    }

    return { date: row.date, ...scores }
  })

  const n = rows.length
  const averages = {
    physical: Math.round((sums.physical / n) * 10) / 10,
    mental: Math.round((sums.mental / n) * 10) / 10,
    emotional: Math.round((sums.emotional / n) * 10) / 10,
    identity: Math.round((sums.identity / n) * 10) / 10,
  }

  const lowestMostOften = Object.entries(lowestCount)
    .sort((a, b) => b[1] - a[1])[0][0]

  res.json({ period, from, to, totalEntries: n, averages, lowestMostOften, dailyScores })
})

// GET /api/checkins/export
router.get('/export', (req, res) => {
  let query = 'SELECT * FROM checkins'
  const conditions = []
  const params = []

  if (req.query.from) { conditions.push('date >= ?'); params.push(req.query.from) }
  if (req.query.to) { conditions.push('date <= ?'); params.push(req.query.to) }
  if (conditions.length) query += ' WHERE ' + conditions.join(' AND ')
  query += ' ORDER BY date ASC'

  const rows = db.prepare(query).all(...params)

  const headers = [
    'date', 'physicalScore', 'physicalHelped', 'physicalDrained',
    'mentalScore', 'mentalHelped', 'mentalDrained',
    'emotionalScore', 'emotionalHelped', 'emotionalDrained',
    'identityScore', 'identityHelped', 'identityDrained',
    'dominoEffect', 'feltMostLikeMyself', 'feltLeastLikeMyself',
    'needTomorrow', 'partnerShouldUnderstand',
  ]

  const csvRows = [headers.join(',')]
  for (const row of rows) {
    csvRows.push(headers.map(h => {
      const val = String(row[h] ?? '')
      return val.includes(',') || val.includes('"') || val.includes('\n')
        ? `"${val.replace(/"/g, '""')}"`
        : val
    }).join(','))
  }

  res.setHeader('Content-Type', 'text/csv')
  res.setHeader('Content-Disposition', 'attachment; filename="energy-balance-export.csv"')
  res.send(csvRows.join('\n'))
})

// GET /api/checkins/:id
router.get('/:id', (req, res) => {
  const row = db.prepare('SELECT * FROM checkins WHERE id = ?').get(req.params.id)
  if (!row) return res.status(404).json({ error: 'Check-in not found' })
  res.json(row)
})

// GET /api/checkins
router.get('/', (req, res) => {
  let query = 'SELECT * FROM checkins'
  const conditions = []
  const params = []

  if (req.query.from) { conditions.push('date >= ?'); params.push(req.query.from) }
  if (req.query.to) { conditions.push('date <= ?'); params.push(req.query.to) }
  if (conditions.length) query += ' WHERE ' + conditions.join(' AND ')
  query += ' ORDER BY date DESC'

  res.json(db.prepare(query).all(...params))
})

// POST /api/checkins
router.post('/', (req, res) => {
  const errors = validateCheckIn(req.body)
  if (errors.length) return res.status(400).json({ error: errors.join('; ') })

  const existing = db.prepare('SELECT id FROM checkins WHERE date = ?').get(req.body.date)
  if (existing) {
    return res.status(409).json({
      error: 'A check-in already exists for this date',
      existingId: existing.id,
    })
  }

  const data = sanitizeCheckIn(req.body)
  const now = new Date().toISOString()

  const stmt = db.prepare(`
    INSERT INTO checkins (
      date, physicalScore, physicalHelped, physicalDrained,
      mentalScore, mentalHelped, mentalDrained,
      emotionalScore, emotionalHelped, emotionalDrained,
      identityScore, identityHelped, identityDrained,
      dominoEffect, feltMostLikeMyself, feltLeastLikeMyself,
      needTomorrow, partnerShouldUnderstand, createdAt, updatedAt
    ) VALUES (
      @date, @physicalScore, @physicalHelped, @physicalDrained,
      @mentalScore, @mentalHelped, @mentalDrained,
      @emotionalScore, @emotionalHelped, @emotionalDrained,
      @identityScore, @identityHelped, @identityDrained,
      @dominoEffect, @feltMostLikeMyself, @feltLeastLikeMyself,
      @needTomorrow, @partnerShouldUnderstand, @createdAt, @updatedAt
    )
  `)

  const result = stmt.run({ ...data, createdAt: now, updatedAt: now })
  const row = db.prepare('SELECT * FROM checkins WHERE id = ?').get(result.lastInsertRowid)
  res.status(201).json(row)
})

// PUT /api/checkins/:id
router.put('/:id', (req, res) => {
  const existing = db.prepare('SELECT * FROM checkins WHERE id = ?').get(req.params.id)
  if (!existing) return res.status(404).json({ error: 'Check-in not found' })

  const errors = validateCheckIn(req.body)
  if (errors.length) return res.status(400).json({ error: errors.join('; ') })

  if (req.body.date !== existing.date) {
    const dateConflict = db.prepare('SELECT id FROM checkins WHERE date = ? AND id != ?')
      .get(req.body.date, req.params.id)
    if (dateConflict) {
      return res.status(409).json({
        error: 'A check-in already exists for this date',
        existingId: dateConflict.id,
      })
    }
  }

  const data = sanitizeCheckIn(req.body)
  const now = new Date().toISOString()

  db.prepare(`
    UPDATE checkins SET
      date = @date, physicalScore = @physicalScore,
      physicalHelped = @physicalHelped, physicalDrained = @physicalDrained,
      mentalScore = @mentalScore, mentalHelped = @mentalHelped, mentalDrained = @mentalDrained,
      emotionalScore = @emotionalScore, emotionalHelped = @emotionalHelped, emotionalDrained = @emotionalDrained,
      identityScore = @identityScore, identityHelped = @identityHelped, identityDrained = @identityDrained,
      dominoEffect = @dominoEffect, feltMostLikeMyself = @feltMostLikeMyself,
      feltLeastLikeMyself = @feltLeastLikeMyself, needTomorrow = @needTomorrow,
      partnerShouldUnderstand = @partnerShouldUnderstand, updatedAt = @updatedAt
    WHERE id = @id
  `).run({ ...data, updatedAt: now, id: req.params.id })

  const row = db.prepare('SELECT * FROM checkins WHERE id = ?').get(req.params.id)
  res.json(row)
})

// DELETE /api/checkins/:id
router.delete('/:id', (req, res) => {
  const result = db.prepare('DELETE FROM checkins WHERE id = ?').run(req.params.id)
  if (result.changes === 0) return res.status(404).json({ error: 'Check-in not found' })
  res.status(204).end()
})

export default router
"}

Write {"file_path":"D:\code\myEnergy\frontend\src\pages\Dashboard.jsx","content":"import { useState, useEffect } from 'react'
import { Link } from 'react-router-dom'
import { getToday } from '../api/checkins'
import ScoreCard from '../components/ScoreCard'
import BalanceIndicator from '../components/BalanceIndicator'

const CATEGORIES = [
  { key: 'physicalScore', label: 'Physical', color: 'calm' },
  { key: 'mentalScore', label: 'Mental', color: 'sky' },
  { key: 'emotionalScore', label: 'Emotional', color: 'warmth' },
  { key: 'identityScore', label: 'Identity / Purpose', color: 'soul' },
]

const GENTLE_MESSAGES = {
  Physical: 'Consider what your body needs right now — rest, movement, or nourishment.',
  Mental: 'Your mind might benefit from a break, a walk, or some quiet time.',
  Emotional: 'Think about what would help you feel more connected or at ease.',
  'Identity / Purpose': 'Consider what would help you feel more like yourself.',
}

export default function Dashboard() {
  const [checkin, setCheckin] = useState(null)
  const [loading, setLoading] = useState(true)
  const [noEntry, setNoEntry] = useState(false)

  useEffect(() => {
    getToday()
      .then(setCheckin)
      .catch(() => setNoEntry(true))
      .finally(() => setLoading(false))
  }, [])

  if (loading) {
    return <div className="text-center text-gray-400 py-20">Loading...</div>
  }

  if (noEntry || !checkin) {
    return (
      <div className="text-center py-20">
        <h1 className="text-2xl font-semibold text-gray-700 mb-3">Welcome</h1>
        <p className="text-gray-500 mb-6">
          You haven't checked in today yet. Take a few minutes to reflect on your energy.
        </p>
        <Link
          to="/checkin"
          className="inline-block px-6 py-3 bg-calm-500 text-white rounded-xl font-medium hover:bg-calm-600 transition-colors"
        >
          Start Today's Check-In
        </Link>
      </div>
    )
  }

  const scores = CATEGORIES.map(c => ({
    ...c,
    score: checkin[c.key],
  }))

  const average = Math.round(
    (scores.reduce((sum, s) => sum + s.score, 0) / scores.length) * 10
  ) / 10

  const minScore = Math.min(...scores.map(s => s.score))
  const allEqual = scores.every(s => s.score === minScore)
  const lowestCategories = allEqual ? [] : scores.filter(s => s.score === minScore)

  return (
    <div>
      <h1 className="text-2xl font-semibold text-gray-700 mb-6">Today</h1>

      <div className="grid grid-cols-2 gap-3 mb-6">
        {scores.map(s => (
          <ScoreCard
            key={s.key}
            label={s.label}
            score={s.score}
            color={s.color}
            isLowest={lowestCategories.some(l => l.key === s.key)}
          />
        ))}
      </div>

      <BalanceIndicator average={average} />

      {allEqual ? (
        <p className="text-center text-calm-600 mt-6 text-sm">
          Your energy feels balanced today.
        </p>
      ) : lowestCategories.length > 0 && (
        <div className="mt-6 bg-warmth-50 rounded-xl p-4 text-center">
          <p className="text-sm text-gray-600">
            Your lowest energy today is{' '}
            <span className="font-medium">
              {lowestCategories.map(l => l.label).join(' and ')}
            </span>.
          </p>
          <p className="text-sm text-gray-500 mt-1">
            {GENTLE_MESSAGES[lowestCategories[0].label]}
          </p>
        </div>
      )}

      <div className="mt-6 text-center">
        <Link
          to="/checkin"
          className="text-sm text-calm-600 hover:text-calm-700 font-medium"
        >
          Edit today's check-in
        </Link>
      </div>
    </div>
  )
}
"}

