import { useParams, useNavigate } from 'react-router-dom'
import { getToday, getCheckIn, createCheckIn, updateCheckIn } from '../api/checkins'
import CheckInForm from '../components/CheckInForm'

export default function CheckIn() {
  const { id } = useParams()
  const navigate = useNavigate()
  const [initialData, setInitialData] = useState(null)
  const [existingId, setExistingId] = useState(null)
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [saved, setSaved] = useState(false)
  const [error, setError] = useState(null)

  useEffect(() => {
    const load = async () => {
      try {
        if (id) {
          const data = await getCheckIn(id)
          setInitialData(data)
          setExistingId(data.id)
        } else {
          const today = await getToday()
          setInitialData(today)
          setExistingId(today.id)
        }
      } catch {
        // No existing check-in — start fresh
      } finally {
        setLoading(false)
      }
    }
    load()
  }, [id])

  const handleSubmit = async (formData) => {
    setSaving(true)
    setError(null)
    setSaved(false)

    try {
      if (!formData.date) {
        formData.date = new Date().toISOString().split('T')[0]
      }

      if (existingId) {
        await updateCheckIn(existingId, formData)
      } else {
        const result = await createCheckIn(formData)
        setExistingId(result.id)
      }
      setSaved(true)
      setTimeout(() => setSaved(false), 3000)
    } catch (err) {
      if (err.message.includes('already exists')) {
        setError('A check-in already exists for this date. Try editing it from the history page.')
      } else {
        setError(err.message)
      }
    } finally {
      setSaving(false)
    }
  }

  if (loading) {
    return <div className="text-center text-gray-400 py-20">Loading...</div>
  }

  return (
    <div>
      <div className="flex items-center justify-between mb-6">
        <h1 className="text-2xl font-semibold text-gray-700">
          {id ? 'Edit Check-In' : "Today's Check-In"}
        </h1>
        {id && (
          <button
