import { getTrends } from '../api/checkins'
import TrendChart from '../components/TrendChart'
import PatternSummary from '../components/PatternSummary'

const PERIODS = [
  { value: '7d', label: '7 days' },
  { value: '14d', label: '14 days' },
  { value: '30d', label: '30 days' },
  { value: '90d', label: '90 days' },
]

const CATEGORY_COLORS = {
  physical: { label: 'Physical', class: 'bg-calm-500' },
  mental: { label: 'Mental', class: 'bg-sky-500' },
  emotional: { label: 'Emotional', class: 'bg-warmth-500' },
  identity: { label: 'Identity / Purpose', class: 'bg-soul-500' },
}

export default function Trends() {
  const [period, setPeriod] = useState('7d')
  const [trends, setTrends] = useState(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    setLoading(true)
    getTrends(period)
      .then(setTrends)
      .catch(() => setTrends(null))
      .finally(() => setLoading(false))
  }, [period])

  if (loading) {
    return <div className="text-center text-gray-400 py-20">Loading...</div>
  }

  return (
    <div>
      <h1 className="text-2xl font-semibold text-gray-700 mb-6">Trends</h1>

      <div className="flex gap-2 mb-6 overflow-x-auto">
        {PERIODS.map(p => (
          <button
            key={p.value}
            onClick={() => setPeriod(p.value)}
            className={`px-4 py-2 rounded-lg text-sm font-medium whitespace-nowrap transition-colors ${
              period === p.value
                ? 'bg-calm-500 text-white'
                : 'bg-white text-gray-500 hover:bg-gray-50 border border-gray-200'
            }`}
          >
            {p.label}
          </button>
        ))}
      </div>

      {!trends || trends.totalEntries < 2 ? (
        <div className="text-center py-16">
          <p className="text-gray-500 mb-2">Not enough data yet</p>
          <p className="text-sm text-gray-400">
            Keep logging your energy to see patterns emerge. You need at least two check-ins.
          </p>
        </div>
      ) : (
        <>
          <div className="bg-white rounded-xl shadow-sm p-4 mb-6">
            <h2 className="text-sm font-medium text-gray-500 mb-4">Energy Over Time</h2>
            <TrendChart data={trends.dailyScores} />
          </div>

          <div className="grid grid-cols-2 gap-3 mb-6">
            {Object.entries(trends.averages).map(([key, avg]) => (
              <div key={key} className="bg-white rounded-xl shadow-sm p-4">
                <div className="flex items-center gap-2 mb-1">
                  <span className={`w-2.5 h-2.5 rounded-full ${CATEGORY_COLORS[key].class}`} />
                  <span className="text-xs text-gray-500">{CATEGORY_COLORS[key].label}</span>
                </div>
                <span className="text-xl font-semibold text-gray-700">{avg}</span>
                <span className="text-xs text-gray-400 ml-1">avg</span>
              </div>
            ))}
          </div>

          {trends.lowestMostOften && (
            <div className="bg-warmth-50 rounded-xl p-4 mb-6">
              <p className="text-sm text-gray-600">
                <span className="font-medium">
                  {CATEGORY_COLORS[trends.lowestMostOften]?.label}
                </span>{' '}
                has been your lowest energy most often during this period.
              </p>
            </div>
          )}

          <PatternSummary trends={trends} />
        </>
      )}
    </div>
  )
}
"}

