const colorConfig = {
  calm: { text: 'text-calm-700', bg: 'bg-calm-100', fill: 'bg-calm-500', thumb: '#629978' },
  sky: { text: 'text-sky-700', bg: 'bg-sky-100', fill: 'bg-sky-500', thumb: '#3c8ec0' },
  warmth: { text: 'text-warmth-700', bg: 'bg-warmth-100', fill: 'bg-warmth-500', thumb: '#d6854b' },
  soul: { text: 'text-soul-700', bg: 'bg-soul-100', fill: 'bg-soul-500', thumb: '#8e76be' },
}

export default function ScoreSlider({ label, value, onChange, color = 'calm' }) {
  const colors = colorConfig[color] || colorConfig.calm
  const percentage = useMemo(() => ((value - 1) / 9) * 100, [value])

  return (
    <div className="space-y-2">
      <div className="flex items-baseline justify-between">
        <span className={`text-sm font-medium ${colors.text}`}>{label}</span>
        <span className={`text-2xl font-semibold tabular-nums ${colors.text}`}>
          {value}
        </span>
      </div>

      <div className="relative">
        <div className={`absolute inset-x-0 top-1/2 -translate-y-1/2 h-2 rounded-full ${colors.bg}`} />
        <div
          className={`absolute left-0 top-1/2 -translate-y-1/2 h-2 rounded-full ${colors.fill} transition-all duration-150`}
          style={{ width: `${percentage}%` }}
        />
        <input
          type="range"
          min={1}
          max={10}
          step={1}
          value={value}
          onChange={(e) => onChange(Number(e.target.value))}
          className="relative w-full h-11 cursor-pointer appearance-none bg-transparent slider-thumb"
          style={{ '--thumb-color': colors.thumb }}
          aria-label={`${label} score`}
        />
      </div>

      <div className="flex justify-between text-xs text-gray-400 px-0.5">
        <span>1</span>
        <span>5</span>
        <span>10</span>
      </div>
    </div>
  )
}
"}

