import { resolve, dirname } from 'path'
import { fileURLToPath } from 'url'

const __dirname = dirname(fileURLToPath(import.meta.url))
const root = resolve(__dirname, '..')

const backend = spawn('node', ['--watch', 'src/index.js'], {
  cwd: resolve(root, 'backend'),
  stdio: 'pipe',
  shell: true,
})

const frontend = spawn('npx', ['vite'], {
  cwd: resolve(root, 'frontend'),
  stdio: 'pipe',
  shell: true,
})

function prefix(stream, tag, color) {
  stream.on('data', (data) => {
    const lines = data.toString().split('\n').filter(Boolean)
    for (const line of lines) {
      console.log(`${color}[${tag}]\x1b[0m ${line}`)
    }
  })
}

prefix(backend.stdout, 'api', '\x1b[36m')
prefix(backend.stderr, 'api', '\x1b[36m')
prefix(frontend.stdout, ' ui', '\x1b[35m')
prefix(frontend.stderr, ' ui', '\x1b[35m')

function shutdown() {
  backend.kill()
  frontend.kill()
  process.exit(0)
}

process.on('SIGINT', shutdown)
process.on('SIGTERM', shutdown)

backend.on('exit', (code) => {
  if (code !== null) {
    console.log('\x1b[36m[api]\x1b[0m exited with code', code)
    frontend.kill()
